fn isTrivia(_: TokenCat) bool {
    return false;
}

const repairTokens = [_]u16{};
const repairOffsets = [_]u32{};

fn repairClass(_: u16) RepairClass {
    return .none;
}

fn ruleSideLabels(rule: u16) []const SideLabel {
    _ = rule;
    return &.{};
}

