/// Slot of `role` in nodes of `kind` (the head is slot 0).
fn slotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"root" => switch (role) {
            .@"doc" => 1,
            else => null,
        },
        .@"container_decl" => switch (role) {
            .@"layout" => 1,
            .@"kind" => 2,
            .@"enum" => 3,
            .@"arg" => 4,
            .@"doc" => 5,
            else => null,
        },
        .@"container_field" => switch (role) {
            .@"doc" => 1,
            .@"comptime" => 2,
            .@"name" => 3,
            .@"type" => 4,
            .@"align" => 5,
            .@"value" => 6,
            else => null,
        },
        .@"test_decl" => switch (role) {
            .@"name" => 1,
            .@"body" => 2,
            else => null,
        },
        .@"fn_decl" => switch (role) {
            .@"proto" => 1,
            .@"body" => 2,
            else => null,
        },
        .@"fn_proto" => switch (role) {
