/// First slot of rest role `role` in nodes of `kind`.
fn restSlotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"root" => if (role == .@"members") 2 else null,
        .@"tokens" => if (role == .@"tokens") 1 else null,
        .@"container_decl" => if (role == .@"members") 6 else null,
        .@"block" => if (role == .@"statements") 2 else null,
        .@"switch" => if (role == .@"cases") 3 else null,
        .@"call" => if (role == .@"args") 2 else null,
        .@"builtin_call" => if (role == .@"args") 2 else null,
        .@"struct_init" => if (role == .@"fields") 2 else null,
        .@"array_init" => if (role == .@"elements") 2 else null,
        .@"multiline_string_literal" => if (role == .@"lines") 1 else null,
        .@"asm" => if (role == .@"items") 4 else null,
        .@"ptr_type" => if (role == .@"quals") 8 else null,
        .@"error_set_decl" => if (role == .@"members") 1 else null,
        else => null,
    };
}

